pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    Succeeder callee;

    function setUp() public {
        c = new C();
        callee = new Succeeder();
    }

    function testFuzz_property(address actor, bytes calldata data) public {
        vm.assume(actor != address(0));
        vm.prank(actor);
        bool ok;
        try c.forward(address(callee), data) {
