pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    function testFuzz_property(address newOwner) public {
        vm.assume(newOwner != address(0));
        address originalOwner = c.owner();

        Writer w = new Writer();
        bytes memory data = abi.encodeWithSelector(w.setOwner.selector, newOwner);
        c.forward(address(w), data);

        // Rule: forward() (a plain call) never mutates C's own storage;
        // owner must remain unchanged for every admissible input.
        assertTrue(c.owner() == originalOwner, "owner changed");
    }
}

contract Writer {
    function setOwner(address a) external {
        assembly { sstore(0, a) }
    }
}

