pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 seed) public {
        vm.assume(seed >= 0); // keep the fuzz domain wide; seed does not gate the property
        // Adversarial counterparty: a callee that ALWAYS reverts when called.
        Reverter r = new Reverter();
        // Drive c through `forward` targeting the reverting callee.
        bool ok;
        try c.forward(address(r), "") { ok = true; } catch { ok = false; }
        // GENERAL RULE: forwarding to a reverting callee must revert.
        // Reference P: low-level call to `r` fails -> require(_s) reverts -> ok == false.
        // Mutant M: call is redirected to `owner` (this test contract, which accepts the
        // empty-data call) -> it succeeds -> ok == true -> assertion fails.
        assertTrue(ok == false, "forward to a reverting callee must revert");
    }
}

contract Reverter {
    fallback() external payable { revert(); }
}

contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    function run(address callee, bytes memory data) public {
        require(callee == address(this));
        bool ok = c.forward(callee, data);
        assert(!ok);
    }

    fallback() external payable {
        revert();
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address callee, bytes memory data) public payable {
        require(callee == address(this));
        bool reverted;
        try c.forward(callee, data) { reverted = false; } catch { reverted = true; }
        assert(reverted);
    }
    receive() external payable { revert("no"); }
}

